pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address depositor, address collector) public {
        vm.assume(depositor != address(0) && collector != address(0));
        vm.assume(depositAmount > 0);

        c.SetLogFile(address(this));
        c.Initialized();

        // Deposit from depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        uint256 initialBalanceCollector = c.balances(collector);

        // Collector attempts to collect
        vm.prank(collector);
        try c.Collect(collectAmount) {} catch {}

        uint256 finalBalanceCollector = c.balances(collector);

        // Invariant: balance after collect cannot exceed initial balance (it should only decrease or stay same if failed)
        assertTrue(finalBalanceCollector <= initialBalanceCollector || (collector == depositor && finalBalanceCollector == c.balances(depositor)));
    }
}

