pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address user, address other) public {
        vm.assume(user != address(0) && other != address(0) && user != other);
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0);

        // Initialize contract and set a minimum sum low enough to allow collects
        c.SetMinSum(0);
        c.SetLogFile(address(0x0000000000000000000000000000000000000000));
        c.Initialized();

        // Fund and deposit from two distinct users to populate balances
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Deposit{value: depositAmt}();

        vm.deal(other, depositAmt);
        vm.prank(other);
        c.Deposit{value: depositAmt}();

        // Record the total deposits (sum of both users' deposits)
        uint256 totalDeposited = depositAmt * 2;

        // Record balances before collect
        uint256 userBalBefore = c.balances(user);
        uint256 otherBalBefore = c.balances(other);

        // User performs a collect
        vm.prank(user);
        try c.Collect(collectAmt) { } catch { }

        // Balances after collect
        uint256 userBalAfter = c.balances(user);
        uint256 otherBalAfter = c.balances(other);

        // Determine actual amount successfully collected by user
        uint256 actualCollected;
        if (collectAmt <= userBalBefore && userBalBefore >= c.MinSum()) {
            // collect should have succeeded and reduced balance
            actualCollected = collectAmt;
        } else {
            // collect should have failed, no balance change
            actualCollected = 0;
        }

        // Total withdrawals from the contract (only user could have withdrawn)
        uint256 totalWithdrawn = actualCollected;

        // Expected total balance sum = total deposits - total withdrawals
        uint256 expectedSum = totalDeposited - totalWithdrawn;

        // Actual total balance sum
        uint256 actualSum = userBalAfter + otherBalAfter;

        // The invariant: sum of all balances == total deposits (via Deposit) minus total successful withdrawals
        assertTrue(actualSum == expectedSum);
    }
}

