pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(depositAmount > 0 && collectAmount > 0);
        vm.assume(depositAmount < type(uint256).max / 2 && collectAmount < type(uint256).max / 2);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0x1));
        c.Initialized();

        // Record ether balance before deposit
        uint256 contractBalanceBefore = address(c).balance;

        // Deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 contractBalanceAfterDeposit = address(c).balance;

        // Ensure collect is possible
        vm.assume(collectAmount <= depositAmount);

        // Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 contractBalanceAfterCollect = address(c).balance;

        // Rule: ether balance after collect must equal deposits minus collected amount
        // Correct version: balance = depositAmount; after collect = depositAmount - collectAmount
        // Buggy version: balance = depositAmount; after collect = depositAmount (since balances not updated, but ether sent)
        // So in buggy, contractBalanceAfterCollect = depositAmount - collectAmount (ether sent), but balances[actor] still 0, so sum consistency broken
        // The invariant: contract balance reflects total deposited minus collected
        uint256 expectedBalance = contractBalanceAfterDeposit - collectAmount;
        assertTrue(contractBalanceAfterCollect == expectedBalance);
    }
}
